		'@angular-devkit/build-angular': '~13.3.11',
		rxjs: '~6.6.7',
		'rxjs-compat': '~6.6.7',
		'zone.js': '~0.11.8',
		tslib: '^2.6.3',
		typescript: '~4.6.4',
